import networkx as nx
G = nx.Graph()
G.add_nodes_from(range(20))
G.add_edges_from([(1,18), (4,18), (16,18), (4,19), (17,18), (11,19), (3,19)])
for u in range(20):
    for v in range(u+1, 20):
        if (u, v) not in G.edges and (v, u) not in G.edges:
            G.add_edge(u, v)
            if len(list(nx.find_cycle(G))) > 0:
                G.remove_edge(u, v)
print(list(G.edges))
